INSERT INTO "Habilidade" ("id", "codigo", "nome", "descricao", "classe", "tipo", "elemento", "icone", "custo", "cooldown", "dano", "alcance", "raio", "duracao", "efeito", "potencia", "nivelReq", "ultimate", "aprendizado", "atualizadoEm") VALUES
('hab_corte_da_mare', 'corte_da_mare', 'Corte da Maré', 'Primeira forma. Um arco de lâmina à sua frente, como uma onda: fere, deixa lento e empurra todos.', 'SAMURAI', 'AREA', 'GELO', 'minecraft:heart_of_the_sea', 15, 4, 6, 6, 0, 0, 'frx:leque', 0, 1, false, 'NIVEL', CURRENT_TIMESTAMP),
('hab_passo_relampago', 'passo_relampago', 'Passo Relâmpago', 'Avança 9 blocos num piscar, cortando quem estiver no caminho.', 'SAMURAI', 'MOBILIDADE', 'RAIO', 'minecraft:lightning_rod', 15, 6, 4, 9, 0, 0, '', 0, 2, false, 'NIVEL', CURRENT_TIMESTAMP),
('hab_corte_sangrento', 'corte_sangrento', 'Corte Sangrento', 'Um corte fundo no alvo, que sangra por 5 s: metade do dano a cada segundo.', 'SAMURAI', 'ALVO', 'FISICO', 'minecraft:redstone', 20, 8, 6, 4.5, 0, 5, 'frx:sangria', 0, 4, false, 'NIVEL', CURRENT_TIMESTAMP),
('hab_guarda_do_bambu', 'guarda_do_bambu', 'Guarda do Bambu', 'Postura de aparar por 3 s: 60% do dano que você receber volta em quem atacou.', 'SAMURAI', 'BUFF', 'FISICO', 'minecraft:bamboo', 20, 14, 0, 0, 0, 3, 'frx:refletir', 6, 5, false, 'NIVEL', CURRENT_TIMESTAMP),
('hab_presa_da_brasa', 'presa_da_brasa', 'Presa da Brasa', 'Segunda forma. Uma estocada em chamas em linha reta que atravessa todos; quanto mais longe, mais forte.', 'SAMURAI', 'SKILLSHOT', 'FOGO', 'minecraft:blaze_rod', 25, 9, 7, 10, 0, 0, 'frx:perfurar', 0, 7, false, 'NIVEL', CURRENT_TIMESTAMP),
('hab_lua_minguante', 'lua_minguante', 'Lua Minguante', 'Some num clarão e reaparece atrás do alvo da mira, já com o corte.', 'SAMURAI', 'ALVO', 'RAIO', 'minecraft:ender_eye', 25, 10, 8, 12, 0, 0, 'frx:atras', 0, 8, false, 'NIVEL', CURRENT_TIMESTAMP),
('hab_redemoinho_da_mare', 'redemoinho_da_mare', 'Redemoinho da Maré', 'Um giro de lâmina que fere todos a até 5 blocos e os prende no lugar por 2 s.', 'SAMURAI', 'AREA', 'GELO', 'minecraft:nautilus_shell', 30, 16, 6, 0, 5, 2, 'frx:congelar', 0, 10, false, 'NIVEL', CURRENT_TIMESTAMP),
('hab_mente_vazia', 'mente_vazia', 'Mente Vazia', 'Embainha a katana e esvazia a mente por 4 s: recupera vida e 40 de energia, e limpa efeitos ruins.', 'SAMURAI', 'BUFF', 'ARCANO', 'minecraft:cherry_sapling', 0, 30, -2, 0, 0, 4, 'frx:meditar', 5, 12, false, 'NIVEL', CURRENT_TIMESTAMP),
('hab_danca_das_petalas', 'danca_das_petalas', 'Dança das Pétalas', 'Salta entre até 5 inimigos a até 8 blocos, um corte pelas costas em cada, e volta ao ponto de partida.', 'SAMURAI', 'AREA', 'FISICO', 'minecraft:pink_petals', 35, 18, 7, 0, 8, 0, 'frx:danca', 5, 14, false, 'NIVEL', CURRENT_TIMESTAMP),
('hab_ultimo_suspiro', 'ultimo_suspiro', 'Último Suspiro', 'O golpe de misericórdia: quanto menos vida o alvo tem, mais forte (até o triplo). Se matar, a recarga zera.', 'SAMURAI', 'ALVO', 'FISICO', 'minecraft:wither_rose', 30, 14, 9, 4.5, 0, 0, 'frx:executar', 0, 16, false, 'NIVEL', CURRENT_TIMESTAMP),
('hab_fenda_do_trovao', 'fenda_do_trovao', 'Fenda do Trovão', 'Terceira forma. Um corte que rasga o chão em linha reta e levanta todos os inimigos no caminho. Aprendida com um Tomo Arcano.', 'SAMURAI', 'SKILLSHOT', 'RAIO', 'minecraft:trident', 35, 16, 10, 14, 0, 0, 'frx:fenda', 0, 18, false, 'ITEM', CURRENT_TIMESTAMP),
('hab_tempestade_de_mil_cortes', 'tempestade_de_mil_cortes', 'Tempestade de Mil Cortes', 'Por 6 s, cortes invisíveis acertam sem parar os inimigos a até 6 blocos, e você resiste mais. No fim, um corte final atinge todos com o triplo do dano.', 'SAMURAI', 'AREA', 'FISICO', 'minecraft:netherite_sword', 100, 120, 4, 0, 6, 6, 'frx:cem', 0, 25, true, 'NIVEL', CURRENT_TIMESTAMP)
